<script setup>
import { computed, onUnmounted, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { ArrowLeft, Refresh, Search } from '@element-plus/icons-vue'
import { operateMiddleware } from '../../api/middleware'
import { getUser, getPermissions } from '../../utils/auth'
import { formatKafkaCount as count, kafkaOffsetAtLeast, kafkaOffsetPercent, kafkaPayload, kafkaConfigSource } from './kafka-topic'
const props = defineProps({ sourceId: Number, topic: String })
const router = useRouter(), tab = ref('overview'), overview = ref(null), configs = ref([]), messages = ref(null), consumers = ref(null)
const baseLoading = ref(false), configLoading = ref(false), messagesLoading = ref(false), consumersLoading = ref(false), saving = ref(false)
const errors = reactive({ base:'', configs:'', messages:'', consumers:'' }), revision = ref(0)
const query = reactive({ partition:'0', mode:'latest', offset:'0', timestamp:'', limit:'50' })
const messageFilter = ref(''), configFilter = ref(''), groupFilter = ref(''), messageDetail = ref(null), consumerDetail = ref(null)
const produceDialog = ref(false), configDialog = ref(false), partitionsDialog = ref(false), prettyJSON = ref(true), configEdit = reactive({})
const production = reactive({ partition:'0', key:'', value:'', nullKey:true, tombstone:false, keyEncoding:'utf8', valueEncoding:'utf8', headers:'[]' })
const newPartitions = ref(1), cursorHistory = ref([]), messageScope = ref(null), confirming = ref(false)
let generation = 0, messageRequest = 0, consumerRequest = 0
const can = action => { revision.value; return getUser().accountType === 'administrator' || getPermissions().includes(`assets:middleware:${action}`) }
const partitions = computed(() => overview.value?.partitions || [])
const replication = computed(() => [...new Set(partitions.value.map(p => p.replicas.length))].join(' / ') || '—')
const cleanup = computed(() => configs.value.find(c => c.name === 'cleanup.policy')?.value || '—')
const visibleMessages = computed(() => (messages.value?.items || []).filter(m => `${m.key.text} ${m.value.text} ${m.offset}`.toLowerCase().includes(messageFilter.value.toLowerCase())))
const visibleConfigs = computed(() => configs.value.filter(c => `${c.name} ${c.value}`.toLowerCase().includes(configFilter.value.toLowerCase())))
const maxSpan = computed(() => partitions.value.reduce((max,p) => kafkaOffsetAtLeast(p.offsetSpan,max) ? p.offsetSpan : max,'0'))
const brokerStats = computed(() => { const stats = new Map(); for (const p of partitions.value) { for (const id of p.replicas) { if (!stats.has(id)) stats.set(id,{ id, leaders:0, replicas:0, isr:0 }); const b = stats.get(id); b.replicas++; if (p.leader === id) b.leaders++; if (p.isr.includes(id)) b.isr++ } }; return [...stats.values()].sort((a,b) => a.id-b.id) })
function valid() { return Number.isSafeInteger(props.sourceId) && props.sourceId > 0 && Boolean(props.topic) }
function api(operation, params = {}, action = 'query') { return operateMiddleware(props.sourceId,operation,{...params,name:props.topic},action,action !== 'query') }
function reset() { saving.value=false; baseLoading.value=false;configLoading.value=false;messagesLoading.value=false;consumersLoading.value=false;generation++; messageRequest++; consumerRequest++; tab.value='overview'; overview.value=null; configs.value=[]; messages.value=null; consumers.value=null; cursorHistory.value=[]; Object.keys(errors).forEach(k=>errors[k]=''); Object.assign(query,{partition:'0',mode:'latest',offset:'0',timestamp:'',limit:'50'}); produceDialog.value=false; configDialog.value=false; partitionsDialog.value=false; loadBase() }
watch(() => [props.sourceId,props.topic],reset,{immediate:true})
function permissionsChanged() { revision.value++; overview.value=null; configs.value=[]; messages.value=null; consumers.value=null; loadBase(); if (tab.value === 'messages') loadMessages(); if (tab.value === 'consumers') loadConsumers() }
window.addEventListener('ops-admin-permissions-changed',permissionsChanged)
onUnmounted(()=>{generation++;messageRequest++;consumerRequest++;window.removeEventListener('ops-admin-permissions-changed',permissionsChanged)})
async function loadBase() { if (!valid() || !can('query')) { errors.base = valid() ? '当前没有查询该数据源的权限。' : 'Topic 地址参数不正确。'; return }; const g=generation; baseLoading.value=true; configLoading.value=true; const results = await Promise.allSettled([api('topic.overview'),api('topic.configs')]); if(g!==generation)return; baseLoading.value=false;configLoading.value=false; const [a,b]=results;overview.value=a.status==='fulfilled'?a.value:null;errors.base=a.status==='rejected'?a.reason.message:'';configs.value=b.status==='fulfilled'?b.value:[];errors.configs=b.status==='rejected'?b.reason.message:'' }
async function loadMessages(cursor) { if(!valid() || !can('query'))return; const g=generation,r=++messageRequest;messagesLoading.value=true;errors.messages=''; const params={...(cursor!==undefined && messageScope.value ? messageScope.value : query)};if(cursor!==undefined){params.mode='offset';params.offset=cursor}; if(params.mode==='time'){const d=new Date(params.timestamp);if(Number.isNaN(d.getTime())){ElMessage.warning('请选择有效时间');messagesLoading.value=false;return};params.timestamp=d.toISOString()};try{const data=await api('topic.messages',params);if(g===generation&&r===messageRequest){messages.value=data;messageScope.value={...params}}}catch(e){if(g===generation&&r===messageRequest){errors.messages=e.message;messages.value=null}}finally{if(g===generation&&r===messageRequest)messagesLoading.value=false} }
function searchMessages(){cursorHistory.value=[];loadMessages()}
function nextMessages(){if(!messages.value?.hasMore)return;cursorHistory.value.push(messages.value.items?.[0]?.offset || query.offset);loadMessages(messages.value.nextOffset)}
function previousMessages(){const cursor=cursorHistory.value.pop();if(cursor!==undefined)loadMessages(cursor)}
async function loadConsumers(append=false){if(!valid() || !can('query'))return;const g=generation,r=++consumerRequest;consumersLoading.value=true;errors.consumers='';try{const data=await api('topic.consumers',{groupFilter:groupFilter.value,scanOffset:String(append?consumers.value?.nextScanOffset||0:0)});if(g===generation&&r===consumerRequest)consumers.value=append?{...data,items:[...(consumers.value?.items||[]),...data.items],warnings:[...(consumers.value?.warnings||[]),...data.warnings]}:data}catch(e){if(g===generation&&r===consumerRequest){errors.consumers=e.message;if(!append)consumers.value=null}}finally{if(g===generation&&r===consumerRequest)consumersLoading.value=false}}
function changeTab(){if(tab.value==='messages'&&!messages.value)loadMessages();if(tab.value==='consumers'&&!consumers.value)loadConsumers()}
function refresh(){if(tab.value==='messages')searchMessages();else if(tab.value==='consumers')loadConsumers();else loadBase()}
function back(){router.push({path:'/assets/middleware/kafka',query:{sourceId:props.sourceId}})}
async function confirm(label,description){if(confirming.value||saving.value)return false;confirming.value=true;try{await ElMessageBox.confirm(description,`${label} · ${props.topic}`,{type:'warning',confirmButtonText:'确认执行',cancelButtonText:'取消'});return true}catch{return false}finally{confirming.value=false}}
function openProduce(){Object.assign(production,{partition:String(partitions.value[0]?.id??0),key:'',value:'',nullKey:true,tombstone:false,keyEncoding:'utf8',valueEncoding:'utf8',headers:'[]'});produceDialog.value=true}
async function produce(){try{const h=JSON.parse(production.headers||'[]');if(!Array.isArray(h))throw new Error()}catch{ElMessage.warning('Headers 需要填写 JSON 数组');return};if(!await confirm('发送消息',`向分区 ${production.partition} 发送${production.tombstone?' Tombstone':'一条消息'}？`))return;const g=generation;saving.value=true;try{const data=await api('topic.produce',Object.fromEntries(Object.entries(production).map(([k,v])=>[k,String(v)])),'write');if(g!==generation)return;produceDialog.value=false;ElMessage.success(`发送成功：分区 ${data.partition}，Offset ${data.offset}`);messages.value=null;await loadBase()}finally{if(g===generation)saving.value=false}}
function editConfig(c){Object.assign(configEdit,c);configDialog.value=true}
async function updateConfig(reset=false){if(!await confirm(reset?'恢复默认配置':'修改配置',reset?`移除 Topic 的 ${configEdit.name} 覆盖值，恢复继承 Broker / 默认配置？`:`将 ${configEdit.name} 修改为 ${configEdit.value}？`))return;const g=generation;saving.value=true;try{await api('topic.config.set',{key:configEdit.name,value:configEdit.value,reset:String(reset)},'write');if(g!==generation)return;configDialog.value=false;ElMessage.success('配置已更新');await loadBase()}finally{if(g===generation)saving.value=false}}
async function increasePartitions(){if(!await confirm('增加分区',`将分区总数从 ${partitions.value.length} 增至 ${newPartitions.value}？分区不能减少，按 Key 路由的消息分配可能改变。`))return;const g=generation;saving.value=true;try{await api('topic.partitions',{partitions:String(newPartitions.value)},'write');if(g!==generation)return;partitionsDialog.value=false;ElMessage.success('分区扩容请求已完成');await loadBase()}finally{if(g===generation)saving.value=false}}
function viewPartition(p){query.partition=String(p.id);query.mode='earliest';cursorHistory.value=[];tab.value='messages';loadMessages()}
const displayTime = v => v && !v.startsWith('0001-') ? new Date(v).toLocaleString() : '—'
</script>
<template>
 <section class="topic-page">
  <header class="topic-header"><div class="topic-path"><el-button link type="primary" :icon="ArrowLeft" @click="back">Topics</el-button><span>/</span><h1>{{ topic }}</h1><el-tag v-if="overview" size="small" effect="plain" type="info">{{ overview.internal ? '内部 Topic' : '业务 Topic' }}</el-tag></div><div class="header-actions"><el-button :icon="Refresh" :loading="baseLoading" @click="refresh">刷新</el-button><el-button v-if="can('write')" type="primary" :disabled="!overview" @click="openProduce">发送消息</el-button></div></header>
  <el-alert v-if="errors.base" :title="errors.base" type="error" :closable="false" show-icon/>
  <el-tabs v-model="tab" class="topic-tabs" @tab-change="changeTab"><el-tab-pane label="概览" name="overview"/><el-tab-pane label="消息" name="messages"/><el-tab-pane label="消费者" name="consumers"/><el-tab-pane label="配置" name="settings"/><el-tab-pane label="统计" name="statistics"/></el-tabs>
  <template v-if="tab === 'overview' || tab === 'statistics'">
   <div v-loading="baseLoading" class="topic-metrics"><div><span>分区数</span><strong>{{ overview ? partitions.length : '—' }}</strong></div><div><span>副本因子</span><strong>{{ replication }}</strong></div><div><span>副本不足分区 · URP</span><strong :class="{'danger':overview?.underReplicated}">{{ overview?.underReplicated ?? '—' }}</strong></div><div><span>同步副本 · ISR</span><strong>{{ overview ? `${overview.isrCount} / ${overview.replicaCount}` : '—' }}</strong></div><div><span>清理策略</span><strong>{{ cleanup }}</strong></div><div><span>Offset 跨度</span><strong>{{ count(overview?.offsetSpan) }}</strong></div></div>
   <p class="topic-note">Offset 跨度 = Next Offset − First Offset；压缩、事务和删除可能形成空洞，不代表精确消息条数。{{ overview ? `采样时间：${displayTime(overview.fetchedAt)}` : '' }}</p>
   <template v-if="tab==='overview'"><div class="table-heading"><h2>分区</h2><el-button v-if="can('write')" :disabled="!overview" @click="newPartitions=partitions.length+1;partitionsDialog=true">增加分区</el-button></div><el-table :data="partitions" v-loading="baseLoading" row-key="id" empty-text="暂无分区数据"><el-table-column prop="id" label="Partition ID" width="115"/><el-table-column prop="leader" label="Leader" width="100"/><el-table-column label="Replicas" min-width="120"><template #default="{row}">{{ row.replicas.join(', ') || '—' }}</template></el-table-column><el-table-column label="ISR" min-width="110"><template #default="{row}"><span :class="{'danger':row.isr.length<row.replicas.length}">{{ row.isr.join(', ') || '—' }}</span></template></el-table-column><el-table-column prop="firstOffset" label="First Offset" min-width="140"/><el-table-column prop="nextOffset" label="Next Offset" min-width="140"/><el-table-column label="Offset 跨度" min-width="140"><template #default="{row}">{{count(row.offsetSpan)}}</template></el-table-column><el-table-column label="操作" width="120" fixed="right"><template #default="{row}"><el-tooltip v-if="row.error" :content="row.error"><span class="danger">读取异常</span></el-tooltip><el-button v-else link type="primary" @click="viewPartition(row)">浏览消息</el-button></template></el-table-column></el-table></template>
   <template v-else><div class="table-heading"><h2>分区 Offset 分布</h2></div><el-table :data="partitions"><el-table-column prop="id" label="分区" width="100"/><el-table-column label="Offset 跨度" width="180"><template #default="{row}">{{ count(row.offsetSpan) }}</template></el-table-column><el-table-column label="分布"><template #default="{row}"><el-progress :percentage="kafkaOffsetPercent(row.offsetSpan,maxSpan)" :show-text="false" :stroke-width="10"/></template></el-table-column><el-table-column label="同步状态" width="160"><template #default="{row}">{{ row.isr.length }} / {{ row.replicas.length }}</template></el-table-column></el-table><div class="table-heading"><h2>Broker 副本分布</h2></div><el-table :data="brokerStats"><el-table-column prop="id" label="Broker ID"/><el-table-column prop="leaders" label="Leader 分区数"/><el-table-column prop="replicas" label="副本数"/><el-table-column prop="isr" label="同步副本数"/></el-table><p class="topic-note">当前统计来自 Kafka 元数据与 Offset。日志段大小、磁盘占用及吞吐量需接入 Broker 监控后提供。</p></template>
  </template>
  <template v-else-if="tab==='messages'">
   <div class="message-query"><label>分区<el-select v-model="query.partition" aria-label="消息分区"><el-option v-for="p in partitions" :key="p.id" :label="`Partition ${p.id}`" :value="String(p.id)"/></el-select></label><label>定位方式<el-select v-model="query.mode" aria-label="消息定位方式"><el-option label="最新消息" value="latest"/><el-option label="最早消息" value="earliest"/><el-option label="指定 Offset" value="offset"/><el-option label="指定时间" value="time"/></el-select></label><label v-if="query.mode==='offset'">Offset<el-input v-model="query.offset" placeholder="非负整数" aria-label="消息 Offset"/></label><label v-if="query.mode==='time'">时间<el-date-picker v-model="query.timestamp" type="datetime" placeholder="定位时间"/></label><label>条数<el-select v-model="query.limit" aria-label="消息条数"><el-option v-for="n in [20,50,100,200]" :key="n" :label="String(n)" :value="String(n)"/></el-select></label><el-button type="primary" :loading="messagesLoading" @click="searchMessages">查询</el-button></div>
   <el-alert v-if="errors.messages" :title="errors.messages" type="error" :closable="false" show-icon/><div class="message-filter"><el-input v-model="messageFilter" :prefix-icon="Search" clearable placeholder="筛选本页 Key、Value 或 Offset" aria-label="筛选当前页消息"/><span>直接读取分区，不提交业务消费位点</span></div>
   <el-table :data="visibleMessages" v-loading="messagesLoading" empty-text="当前位置暂无可展示的消息"><el-table-column prop="offset" label="Offset" width="155"/><el-table-column prop="partition" label="分区" width="80"/><el-table-column label="时间" min-width="180"><template #default="{row}">{{displayTime(row.timestamp)}}</template></el-table-column><el-table-column label="Key" min-width="150" show-overflow-tooltip><template #default="{row}">{{kafkaPayload(row.key)}}</template></el-table-column><el-table-column label="Value" min-width="300" show-overflow-tooltip><template #default="{row}"><el-tag v-if="row.value.null" size="small" type="info">Tombstone</el-tag><span v-else>{{kafkaPayload(row.value)}}</span></template></el-table-column><el-table-column label="操作" width="90" fixed="right"><template #default="{row}"><el-button link type="primary" @click="messageDetail=row">详情</el-button></template></el-table-column></el-table>
   <footer class="topic-pagination"><span>{{ visibleMessages.length }} 条{{ messageFilter ? '匹配' : '' }}结果 · 下一 Offset {{ messages?.nextOffset ?? '—' }}</span><el-button :disabled="!cursorHistory.length || messagesLoading" @click="previousMessages">上一页</el-button><el-button :disabled="!messages?.hasMore || messagesLoading" @click="nextMessages">下一页</el-button></footer><p class="topic-note">按分区 Offset 升序读取；单页最多 200 条、4 MiB，单条最多 1 MiB。二进制内容以 Base64 展示。{{messages?.truncated?'本页达到大小限制，可继续下一页。':''}}</p>
  </template>
  <template v-else-if="tab==='consumers'"><div class="message-filter"><el-input v-model="groupFilter" :prefix-icon="Search" clearable placeholder="按消费组名称筛选" aria-label="消费组名称" @keyup.enter="loadConsumers()"/><el-button type="primary" :loading="consumersLoading" @click="loadConsumers()">查询</el-button></div><el-alert v-if="errors.consumers" :title="errors.consumers" type="error" :closable="false"/><el-alert v-if="consumers?.warnings?.length" :title="`有 ${consumers.warnings.length} 个消费组未能完整读取，结果可能不完整`" type="warning" :closable="false"><details><summary>查看原因</summary><p v-for="warning in consumers.warnings" :key="warning">{{warning}}</p></details></el-alert><el-table :data="consumers?.items || []" v-loading="consumersLoading" empty-text="暂无关联消费组"><el-table-column prop="groupId" label="消费组" min-width="230"/><el-table-column prop="members" label="活跃消费者" width="130"/><el-table-column label="Lag" min-width="150"><template #default="{row}">{{count(row.lag)}}</template></el-table-column><el-table-column prop="coordinator" label="Coordinator" width="140"/><el-table-column prop="state" label="状态" width="160"/><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="consumerDetail=row">详情</el-button></template></el-table-column></el-table><footer class="topic-pagination"><span>已检查 {{ consumers?.scanned || 0 }} / {{ consumers?.totalGroups || 0 }} 个消费组；关联 {{ consumers?.items?.length || 0 }} 个</span><el-button v-if="consumers?.hasMore" :loading="consumersLoading" @click="loadConsumers(true)">继续检查</el-button></footer><p class="topic-note">Lag 按已提交 Offset 与分区末尾 Offset 计算；未提交位点的分区显示“—”。每批检查 100 个消费组。</p></template>
  <template v-else-if="tab==='settings'"><el-alert v-if="errors.configs" :title="errors.configs" type="error" :closable="false"/><div class="message-filter"><el-input v-model="configFilter" :prefix-icon="Search" clearable placeholder="筛选配置项或值" aria-label="筛选 Topic 配置"/></div><el-table :data="visibleConfigs" v-loading="configLoading" empty-text="暂无可读取的配置"><el-table-column prop="name" label="配置项" min-width="260"/><el-table-column label="值" min-width="220" show-overflow-tooltip><template #default="{row}">{{row.sensitive?'••••••':row.value || '—'}}</template></el-table-column><el-table-column label="来源" width="175"><template #default="{row}">{{kafkaConfigSource(row.source)}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}">{{row.readOnly?'只读':'可修改'}}</template></el-table-column><el-table-column v-if="can('write')" label="操作" width="100" fixed="right"><template #default="{row}"><el-button link type="primary" :disabled="row.readOnly || row.sensitive" @click="editConfig(row)">编辑</el-button></template></el-table-column></el-table></template>
  <el-dialog :model-value="Boolean(messageDetail)" title="消息详情" width="min(900px,94vw)" class="kafka-topic-dialog" @close="messageDetail=null"><template v-if="messageDetail"><el-descriptions :column="3" border><el-descriptions-item label="分区">{{messageDetail.partition}}</el-descriptions-item><el-descriptions-item label="Offset">{{messageDetail.offset}}</el-descriptions-item><el-descriptions-item label="时间">{{displayTime(messageDetail.timestamp)}}</el-descriptions-item></el-descriptions><div class="payload-heading"><h3>Key / Value</h3><el-switch v-model="prettyJSON" active-text="格式化 JSON"/></div><h4>Key <small>{{messageDetail.key.encoding}} · {{messageDetail.key.size}} bytes</small></h4><pre>{{kafkaPayload(messageDetail.key,prettyJSON)}}</pre><h4>Value <small>{{messageDetail.value.encoding}} · {{messageDetail.value.size}} bytes</small></h4><pre>{{kafkaPayload(messageDetail.value,prettyJSON)}}</pre><h4>Headers</h4><el-table :data="messageDetail.headers"><el-table-column prop="key" label="Key"/><el-table-column label="Value"><template #default="{row}">{{kafkaPayload(row.value)}}</template></el-table-column></el-table></template></el-dialog>
  <el-dialog :model-value="Boolean(consumerDetail)" :title="consumerDetail?.groupId || '消费组详情'" width="min(900px,94vw)" class="kafka-topic-dialog" @close="consumerDetail=null"><template v-if="consumerDetail"><el-table :data="consumerDetail.partitions"><el-table-column prop="id" label="分区"/><el-table-column prop="committedOffset" label="已提交 Offset"/><el-table-column prop="endOffset" label="末尾 Offset"/><el-table-column prop="lag" label="Lag"/><el-table-column prop="error" label="错误" show-overflow-tooltip/></el-table><h4>关联客户端</h4><el-table :data="consumerDetail.clients"><el-table-column prop="clientId" label="Client ID"/><el-table-column prop="host" label="客户端"/><el-table-column prop="memberId" label="Member ID" show-overflow-tooltip/></el-table></template></el-dialog>
  <el-dialog v-model="produceDialog" title="发送消息" width="min(720px,94vw)" class="kafka-topic-dialog" :close-on-click-modal="false" :close-on-press-escape="!saving" :show-close="!saving"><p class="topic-note">目标 Topic：{{topic}}</p><el-form label-position="top" :disabled="saving"><el-form-item label="分区"><el-select v-model="production.partition"><el-option v-for="p in partitions" :key="p.id" :label="`Partition ${p.id}`" :value="String(p.id)"/></el-select></el-form-item><div class="payload-heading"><h4>Key</h4><el-checkbox v-model="production.nullKey">无 Key（null）</el-checkbox></div><el-form-item v-if="!production.nullKey"><el-select v-model="production.keyEncoding"><el-option label="UTF-8" value="utf8"/><el-option label="Base64" value="base64"/></el-select><el-input v-model="production.key" placeholder="Key"/></el-form-item><div class="payload-heading"><h4>Value</h4><el-checkbox v-model="production.tombstone">Tombstone（null Value）</el-checkbox></div><el-form-item v-if="!production.tombstone"><el-select v-model="production.valueEncoding"><el-option label="UTF-8 / JSON" value="utf8"/><el-option label="Base64" value="base64"/></el-select><el-input v-model="production.value" type="textarea" :rows="7" placeholder="消息内容"/></el-form-item><el-form-item label="Headers（JSON 数组，可选）"><el-input v-model="production.headers" type="textarea" :rows="2" placeholder='[{"key":"trace-id","value":"123"}]'/></el-form-item></el-form><template #footer><el-button :disabled="saving" @click="produceDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="produce">发送</el-button></template></el-dialog>
  <el-dialog v-model="configDialog" title="修改 Topic 配置" width="min(600px,94vw)" class="kafka-topic-dialog" :close-on-click-modal="false"><el-form label-position="top" :disabled="saving"><el-form-item label="配置项"><el-input :model-value="configEdit.name" disabled/></el-form-item><el-form-item label="值"><el-input v-model="configEdit.value" type="textarea" :rows="3"/></el-form-item><p class="topic-note">{{configEdit.documentation}}</p></el-form><template #footer><el-button :disabled="saving" @click="updateConfig(true)">恢复默认</el-button><el-button :disabled="saving" @click="configDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="updateConfig()">保存</el-button></template></el-dialog>
  <el-dialog v-model="partitionsDialog" title="增加 Topic 分区" width="min(500px,94vw)" :close-on-click-modal="false"><el-form label-position="top" :disabled="saving"><el-form-item label="新的分区总数"><el-input-number v-model="newPartitions" :min="partitions.length+1" :max="10000"/></el-form-item></el-form><template #footer><el-button :disabled="saving" @click="partitionsDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="increasePartitions">增加分区</el-button></template></el-dialog>
 </section>
